        paragraphs = listOf(
            StoryParagraph("I stared at this apparition, and my eyes were wide with wonder.", "به این پدیده خیره شدم و چشمانم از شگفتی فراخ شده بود."),
            StoryParagraph("Remember, I was a thousand miles from any inhabited region.", "به یاد داشته باش، هزار مایل از هر ناحیه مسکونی دور بودم."),
            StoryParagraph("And this small person did not seem to be either lost, or weary, or hungry, or thirsty, or afraid.", "و این آدم کوچک نه گم‌شده به نظر می‌رسید، نه خسته، نه گرسنه، نه تشنه، نه ترسان."),
            StoryParagraph("He did not look at all like a child lost in the middle of the desert, far from any dwelling.", "اصلاً شبیه کودکی نبود که در میان بیابان گم شده باشد، دور از هر مسکنی."),
            StoryParagraph("When I finally found my voice, I said to him: 'But what are you doing here?'", "چون سرانجام صدايم را یافتم، به او گفتم: «اما تو اینجا چه می‌کنی؟»"),
